#include <list>
#include <optional>
#include <unordered_map>
#include <utility>

class LRUCache {
  using Item = std::pair<int, int>;          // key, value
  int cap_;
  std::list<Item> items_;                    // front = most recent
  std::unordered_map<int, std::list<Item>::iterator> idx_;
public:
  explicit LRUCache(int cap) : cap_(cap) { idx_.reserve(cap > 0 ? cap : 0); }

  std::optional<int> get(int key) {
    auto it = idx_.find(key);
    if (it == idx_.end()) return std::nullopt;
    items_.splice(items_.begin(), items_, it->second);  // O(1), iterator stays valid
    return it->second->second;
  }

  void put(int key, int value) {
    if (cap_ <= 0) return;
    if (auto it = idx_.find(key); it != idx_.end()) {
      it->second->second = value;
      items_.splice(items_.begin(), items_, it->second);
      return;
    }
    if (static_cast<int>(items_.size()) == cap_) {
      idx_.erase(items_.back().first);
      items_.pop_back();
    }
    items_.emplace_front(key, value);
    idx_[key] = items_.begin();
  }
};

